select id, full_name, dept_id, manager_id, job_title, salary, is_remote, level, lag(salary, 1) over w_part prev_salary, stddev_samp(salary) over w_part_2 level_stddev_samp_salary, first_value(level, true) over (order by hire_date, id rows between unbounded preceding and current row) first_known_level, stddev_samp(salary) over w_part_2 level_stddev_samp_salary_2 from employees window w_part as (partition by manager_id order by salary, id), w_part_2 as (partition by level)
